import type { PrismaClient } from "@growdesk/database";
import { DurableChatService } from "../services/durable-chat-service.js";
import { WebHistoryService,type HistoryKind } from "../services/web-history-service.js";
import type { FastifyPluginAsync } from 'fastify';
import type pg from 'pg';
import { WEB_BACKGROUND_ROUTES,WEB_HISTORY_ROUTES,WEB_CHAT_READ_ROUTES,type WebJobCreate,type WebJobListQuery,type WebVoiceLogInput } from '@growdesk/contracts';
import { WebBackgroundService } from '../services/web-background-service.js';
function schema(operationId:string) {
  const route=[...WEB_BACKGROUND_ROUTES,...WEB_HISTORY_ROUTES,...WEB_CHAT_READ_ROUTES].find(r=>r.operationId===operationId)!;
  return {operationId,...(route.body?{body:route.body}:{}),...(route.params?{params:route.params}:{}),...(route.querystring?{querystring:route.querystring}:{}),response:route.responses};
}
export const webBackgroundRoutes:FastifyPluginAsync<{pool:pg.Pool;prisma:PrismaClient}> = async(app,{pool,prisma})=>{
  const service=new WebBackgroundService(pool);
  const auth={preHandler:[app.authenticate]};
  app.post<{Body:WebJobCreate}>('/api/v1/web/jobs',{...auth,schema:schema('createWebJob')},async(req,reply)=>reply.code(201).send({data:await service.create(req.principal!.userId,req.body)}));
  app.get<{Querystring:WebJobListQuery}>('/api/v1/web/jobs',{...auth,schema:schema('listWebJobs')},async req=>({data:await service.list(req.principal!.userId,req.query)}));
  app.get<{Params:{id:string}}>('/api/v1/web/jobs/:id',{...auth,schema:schema('getWebJob')},async req=>({data:await service.get(req.principal!.userId,req.params.id)}));
  for(const action of ['cancel','retry','claim'] as const)app.post<{Params:{id:string};Body:{commandId?:string}}>(`/api/v1/web/jobs/:id/${action}`,{...auth,schema:schema(`${action}WebJob`)},async(req)=>({data:await service.action(req.principal!.userId,req.params.id,action,req.body?.commandId)}));
  app.post<{Body:WebVoiceLogInput}>('/api/v1/web/voice/logs',{...auth,schema:schema('createWebVoiceLog')},async(req,reply)=>reply.code(201).send({data:await service.createVoiceLog(req.principal!.userId,req.body)}));
  app.get<{Querystring:{limit?:number;unreadAsyncOnly?:boolean}}>('/api/v1/web/voice/logs',{...auth,schema:schema('listWebVoiceLogs')},async req=>({data:await service.listVoiceLogs(req.principal!.userId,req.query)}));
  app.get<{Params:{id:string}}>('/api/v1/web/voice/logs/:id',{...auth,schema:schema('getWebVoiceLog')},async req=>({data:await service.getVoiceLog(req.principal!.userId,req.params.id)}));
  app.post<{Params:{id:string};Body:{acknowledged:boolean}}>('/api/v1/web/voice/logs/:id/acknowledge',{...auth,schema:schema('acknowledgeWebVoiceLog')},async req=>({data:await service.acknowledgeVoiceLog(req.principal!.userId,req.params.id,req.body.acknowledged)}));
  app.delete<{Params:{id:string}}>('/api/v1/notifications/:id',{...auth,schema:schema('deleteWebNotification')},async req=>({data:await service.deleteNotification(req.principal!.userId,req.params.id)}));
};

import { Value } from '@sinclair/typebox/value';
import { Type, type TSchema } from '@sinclair/typebox';
import * as C from '@growdesk/contracts';
import { type PrismaClient, type Prisma, BadRequestError, ConcurrencyConflictError } from '@growdesk/database';
import type { UserPrincipal } from '@growdesk/domain';
import { FeedingService } from './feeding-service.js';
import { SleepService } from './sleep-service.js';
import { DiaperService } from './diaper-service.js';
import { FoodService } from './food-service.js';
import { SupplementService } from './supplement-service.js';
import { MedicalService } from './medical-service.js';
import { VaccineService } from './vaccine-service.js';
import { GrowthService } from './growth-service.js';

export interface CareAction { actionId:string;entityType:string;operation:string;summary:string;payload:Record<string,unknown> }
const DeleteBody=Type.Object({id:C.UuidString,baseVersion:Type.String({pattern:'^[1-9][0-9]*$'})},{additionalProperties:false});
const definitions={
  feeding:[C.CreateFeedingRequestSchema,C.UpdateFeedingRequestSchema],
  sleep:[C.CreateSleepRequestSchema,C.UpdateSleepRequestSchema],
  diaper:[C.CreateDiaperRequestSchema,C.UpdateDiaperRequestSchema],
  food:[C.CreateFoodRequestSchema,C.UpdateFoodRequestSchema],
  supplement:[C.CreateSupplementRequestSchema,C.UpdateSupplementRequestSchema],
  growth:[C.CreateGrowthMeasurementRequestSchema,C.UpdateGrowthMeasurementRequestSchema],
  medical:[C.CreateMedicalReportRequestSchema,C.UpdateMedicalReportRequestSchema],
  vaccine:[C.CreateVaccineRecordRequestSchema,C.CreateVaccineRecordRequestSchema],
} as const;
export function validateCareAction(action:CareAction):void {
  if(!Object.hasOwn(definitions,action.entityType)||!['create','update','delete'].includes(action.operation)) throw new BadRequestError('Unsupported care operation','AI_ACTION_UNSUPPORTED');
  if(action.entityType==='vaccine'&&action.operation==='update')throw new BadRequestError('Vaccine corrections require explicit delete and create','AI_ACTION_UNSUPPORTED');
  const pair=definitions[action.entityType as keyof typeof definitions];
  const schema:TSchema=action.operation==='delete'?DeleteBody:action.operation==='update'?Type.Object({...pair[1].properties,id:C.UuidString},{additionalProperties:false}):pair[0];
  if(!Value.Check(schema,action.payload)) throw new BadRequestError('Action payload does not match its canonical record contract','AI_ACTION_INVALID');
  if(action.operation!=='create'&&!Number.isSafeInteger(Number(action.payload.baseVersion))) throw new BadRequestError('Record version exceeds database integer range','AI_ACTION_INVALID');
}
/** Bound transaction facade: domain services join the caller transaction; none can commit it. */
export function joinDomainTransaction(tx:Prisma.TransactionClient):PrismaClient {
  return new Proxy(tx,{get(target,key,receiver){
    if(key==='$transaction') return async(work:(same:Prisma.TransactionClient)=>Promise<unknown>)=>work(tx);
    if(key==='$connect'||key==='$disconnect') throw new Error('Transaction facade cannot own connection lifecycle');
    return Reflect.get(target,key,receiver);
  }}) as PrismaClient;
}
/** Execute only validated canonical commands; identity and baby scope never come from model output. */
export async function executeCareAction(prisma:PrismaClient,principal:UserPrincipal,babyId:string,action:CareAction):Promise<unknown> {
  validateCareAction(action);const {id,...payload}=action.payload;const key=action.actionId;
  switch(action.entityType) {
    case 'feeding': {const s=new FeedingService(prisma);if(action.operation==='create')return s.createFeedingRecord(principal,babyId,payload as C.CreateFeedingRequest,key);if(action.operation==='update')return s.updateFeedingRecord(principal,babyId,String(id),payload as C.UpdateFeedingRequest,key);return s.deleteFeedingRecord(principal,babyId,String(id),Number(payload.baseVersion),key);}
    case 'sleep': {const s=new SleepService(prisma);if(action.operation==='create')return s.createSleepRecord(principal,babyId,payload as C.CreateSleepRequest,key);if(action.operation==='update')return s.updateSleepRecord(principal,babyId,String(id),payload as C.UpdateSleepRequest,key);return s.deleteSleepRecord(principal,babyId,String(id),Number(payload.baseVersion),key);}
    case 'diaper': {const s=new DiaperService(prisma);if(action.operation==='create')return s.createDiaperRecord(principal,babyId,payload as C.CreateDiaperRequest,key);if(action.operation==='update')return s.updateDiaperRecord(principal,babyId,String(id),payload as C.UpdateDiaperRequest,key);return s.deleteDiaperRecord(principal,babyId,String(id),Number(payload.baseVersion),key);}
    case 'food': {const s=new FoodService(prisma);if(action.operation==='create')return s.createFoodRecord(principal,babyId,payload as C.CreateFoodRequest,key);if(action.operation==='update')return s.updateFoodRecord(principal,babyId,String(id),payload as C.UpdateFoodRequest,key);return s.deleteFoodRecord(principal,babyId,String(id),Number(payload.baseVersion),key);}
    case 'supplement': {const s=new SupplementService(prisma);if(action.operation==='create')return s.createSupplementRecord(principal,babyId,payload as C.CreateSupplementRequest,key);if(action.operation==='update')return s.updateSupplementRecord(principal,babyId,String(id),payload as C.UpdateSupplementRequest,key);return s.deleteSupplementRecord(principal,babyId,String(id),Number(payload.baseVersion),key);}
    case 'growth': {const s=new GrowthService(prisma);if(action.operation==='create')return s.createGrowthMeasurement(principal,babyId,payload as C.CreateGrowthMeasurementRequest,key);if(action.operation==='update')return s.updateGrowthMeasurement(principal,babyId,String(id),payload as C.UpdateGrowthMeasurementRequest,key);return s.deleteGrowthMeasurement(principal,babyId,String(id),Number(payload.baseVersion),key);}
    case 'medical': {const service=new MedicalService(prisma);if(action.operation==='create')return service.createMedicalReport(principal,babyId,payload as C.CreateMedicalReportRequest,key);if(action.operation==='update')return service.updateMedicalReport(principal,babyId,String(id),payload as C.UpdateMedicalReportRequest);return service.deleteMedicalReport(principal,babyId,String(id),Number(payload.baseVersion));}
    case 'vaccine': {const service=new VaccineService(prisma);if(action.operation==='create')return service.createVaccineRecord(principal,babyId,payload as C.CreateVaccineRecordRequest,key);const rows=await prisma.$queryRawUnsafe<Array<{version:number}>>('SELECT version FROM vaccine_records WHERE id=$1 AND baby_id=$2 AND deleted_at IS NULL FOR UPDATE',String(id),babyId);if(!rows[0]||rows[0].version!==Number(payload.baseVersion))throw new ConcurrencyConflictError('Vaccine record changed; reload before confirming deletion');return service.deleteVaccineRecord(principal,babyId,String(id));}
    default: throw new BadRequestError('Unsupported action','AI_ACTION_UNSUPPORTED');
  }
}

export class AiProviderUnavailableError extends Error {
  readonly statusCode = 503;
  readonly code = "AI_PROVIDER_NOT_CONFIGURED";

  constructor() {
    super(
      "AI provider is not configured. Configure the approved provider, or explicitly select fixture with a fixture response for tests.",
    );
    this.name = "AiProviderUnavailableError";
  }
}

/** API-side preflight: asynchronous runs must fail clearly before persistence when no provider is usable. */
export function assertAiProviderConfigured(env: NodeJS.ProcessEnv = process.env): void {
  const mode = (env.GROWDESK_AI_PROVIDER ?? "").trim().toLowerCase();
  if (mode === "fixture") {
    if (env.NODE_ENV === "test" && (env.GROWDESK_AI_FIXTURE_RESPONSE ?? env.GROWDESK_AI_FIXTURE_TEXT)) return;
    throw new AiProviderUnavailableError();
  }
  if (mode === "openai-compatible" || mode === "openai" || mode === "compat") {
    const baseUrl = env.GROWDESK_AI_BASE_URL?.trim();
    const apiKey = (env.GROWDESK_AI_API_KEY ?? env.AI_API_KEY ?? env.OPENAI_API_KEY ?? "").trim();
    if(baseUrl && apiKey && env.GROWDESK_AI_MODEL?.trim()) {
      let url:URL;
      try { url=new URL(baseUrl); } catch { throw new AiProviderUnavailableError(); }
      if((url.protocol==='https:'||(url.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(url.hostname)))&&!url.username&&!url.password&&!url.search&&!url.hash)return;
    }
  }
  throw new AiProviderUnavailableError();
}
